//! Lifecycle tool definitions and dispatch.

use super::{ok, rendered, req_str};
use lodestar_core::Lodestar;
use serde_json::{json, Value};

pub(super) fn definitions() -> Vec<Value> {
    vec![
        json!({
            "name": "lodestar_stats",
            "description": "Counts: active goals, open/claimed/done/total tasks, active knowledge. `total_tasks` is every task ever created, any status -- the number that tells a `board`/`stalled` caller whether its own empty result means nothing has ever been set up, or that everything is genuinely clean.",
            "inputSchema": { "type": "object", "properties": {} }
        }),
        json!({
            "name": "backup_database",
            "description": "Create a verified online SQLite backup of the complete Lodestar intent plane. The destination must not already exist.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "Destination path for the SQLite backup." }
                },
                "required": ["path"]
            }
        }),
        json!({
            "name": "reset_database",
            "description": "Destructively clear Lodestar designs/materialization history, constitution, tasks, bindings, conformance audit, and learned knowledge. Requires the exact confirmation token RESET LODESTAR and never touches MindLeak memory.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "confirm": { "type": "string", "description": "Must be exactly RESET LODESTAR." }
                },
                "required": ["confirm"]
            }
        }),
    ]
}

pub(super) fn dispatch(
    engine: &Lodestar,
    name: &str,
    args: &Value,
) -> Option<Result<Value, String>> {
    match name {
        "lodestar_stats" => Some((|| {
            let stats = engine.stats().map_err(|e| e.to_string())?;
            let markdown = format!(
                "| Intent Plane | Count |\n|---|--:|\n| Active goals | {} |\n| Open tasks | {} |\n| Claimed tasks | {} |\n| Done tasks | {} |\n| Total tasks (any status) | {} |\n| Active knowledge | {} |",
                stats.active_goals,
                stats.open_tasks,
                stats.claimed_tasks,
                stats.done_tasks,
                stats.total_tasks,
                stats.active_knowledge
            );
            rendered(markdown, &stats)
        })()),
        "backup_database" => Some((|| {
            let path = req_str(args, "path")?;
            engine.backup_database(path).map_err(|e| e.to_string())?;
            ok(&json!({ "backed_up": true, "path": path }))
        })()),
        "reset_database" => Some((|| {
            let outcome = engine
                .reset_database(req_str(args, "confirm")?)
                .map_err(|e| e.to_string())?;
            ok(&outcome)
        })()),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::super::call;
    use super::*;
    use lodestar_core::GoalKind;

    fn payload(result: Value) -> Value {
        serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap()
    }

    #[test]
    fn stats_and_active_knowledge_agree_after_retirement() {
        let engine = Lodestar::open_in_memory().unwrap();
        let retired = engine
            .record_knowledge("retired lesson", "{}", Some(720.0))
            .unwrap();
        engine
            .record_knowledge("active lesson", "{}", Some(720.0))
            .unwrap();
        engine
            .retire_knowledge(&retired.id, "Reviewer", "measured false", None)
            .unwrap();

        let active = payload(
            call(
                &engine,
                &json!({ "name": "active_knowledge", "arguments": {} }),
            )
            .unwrap(),
        );
        let stats = call(
            &engine,
            &json!({ "name": "lodestar_stats", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(active["count"], json!(1));
        assert_eq!(
            stats["structuredContent"]["active_knowledge"],
            active["count"]
        );
    }

    /// `total_tasks` is the one number that tells a `board`/`stalled` caller
    /// seeing an empty result whether nothing has ever been created here or
    /// everything is genuinely clean -- it must count a task regardless of
    /// which status it is currently in, unlike `open_tasks`.
    #[test]
    fn total_tasks_is_reported_and_the_markdown_names_it() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Counted", "count every task", None)
            .unwrap();
        engine.create_task(&goal.id, "Work", "done").unwrap();

        let stats = call(
            &engine,
            &json!({ "name": "lodestar_stats", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(stats["structuredContent"]["total_tasks"], json!(1));
        assert!(stats["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Total tasks"));
    }

    #[test]
    fn lifecycle_tools_backup_and_require_lodestar_reset_token() {
        let engine = Lodestar::open_in_memory().unwrap();
        engine
            .define_goal(
                GoalKind::Invariant,
                "Keep intent durable",
                "Never erase intent with memory reset",
                None,
            )
            .unwrap();
        let path =
            std::env::temp_dir().join(format!("lodestar-mcp-backup-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);

        call(
            &engine,
            &json!({
                "name": "backup_database",
                "arguments": { "path": path.to_str().unwrap() }
            }),
        )
        .unwrap();
        let restored = Lodestar::open(path.to_str().unwrap()).unwrap();
        assert_eq!(restored.get_constitution().unwrap().len(), 1);
        drop(restored);
        std::fs::remove_file(path).unwrap();

        let rejected = call(
            &engine,
            &json!({
                "name": "reset_database",
                "arguments": { "confirm": "RESET MINDLEAK" }
            }),
        )
        .unwrap_err();
        assert!(rejected.contains("RESET LODESTAR"));
        call(
            &engine,
            &json!({
                "name": "reset_database",
                "arguments": { "confirm": "RESET LODESTAR" }
            }),
        )
        .unwrap();
        assert!(engine.get_constitution().unwrap().is_empty());
    }
}
